const original = {
  name: 'Alice',
  address: { city: 'Seoul' }
};

// 얕은 복사
const shallow = { ...original };
shallow.name = 'Bob';
shallow.address.city = 'Busan';

console.log(original.name);
console.log(original.address.city);

// 깊은 복사
const deep = JSON.parse(JSON.stringify(original));
deep.address.city = 'Incheon';

console.log(original.address.city);
